package barcode

import (
	"fmt"
	"math/bits"
	"strings"
)

const (
	alpha     = "UGQT6J+WP%K2O8R0"
	w         = 2
	weightK   = "alt"
	swap      = true
	hasDecode = true
	both      = true
)

func pats() []int {
	var p []int
	for i := 0; i < 64; i++ {
		if bits.OnesCount(uint(i)) == 3 {
			p = append(p, i)
		}
	}
	return p
}

func weight(i int) int {
	switch weightK {
	case "inc":
		return i + 1
	case "odd":
		return 2*i + 1
	}
	if i%2 == 0 {
		return 1
	}
	return 3
}

func startStop() (int, int) {
	p := pats()
	if swap {
		return p[17], p[16]
	}
	return p[16], p[17]
}

func symBars(p int) string {
	var sb strings.Builder
	for j := 0; j < 6; j++ {
		bit := (p >> (5 - j)) & 1
		ch := "#"
		if j%2 == 1 {
			ch = "."
		}
		n := 1
		if bit == 1 {
			n = w
		}
		sb.WriteString(strings.Repeat(ch, n))
	}
	return sb.String()
}

func encode(text string) string {
	if len(text) < 1 || len(text) > 20 {
		return "error: length"
	}
	vals := make([]int, 0, len(text))
	for i := 0; i < len(text); i++ {
		v := strings.IndexByte(alpha, text[i])
		if v < 0 {
			return "error: char " + string(text[i])
		}
		vals = append(vals, v)
	}
	sum := 0
	for i, v := range vals {
		sum += weight(i) * v
	}
	p := pats()
	start, stop := startStop()
	syms := []int{start}
	for _, v := range vals {
		syms = append(syms, p[v])
	}
	syms = append(syms, p[sum%16], stop)
	var sb strings.Builder
	for _, s := range syms {
		sb.WriteString(symBars(s))
	}
	sb.WriteString("#")
	return sb.String()
}

func runsOf(s string) []int {
	var runs []int
	for i := 0; i < len(s); {
		j := i
		for j < len(s) && s[j] == s[i] {
			j++
		}
		runs = append(runs, j-i)
		i = j
	}
	return runs
}

func attempt(s string) (string, string) {
	runs := runsOf(s)
	if runs[len(runs)-1] != 1 {
		return "", "terminator"
	}
	p := pats()
	start, stop := startStop()
	var got []int
	for idx, k := 0, 0; idx < len(runs)-1; idx, k = idx+6, k+1 {
		v := 0
		for _, r := range runs[idx : idx+6] {
			v *= 2
			if r == w {
				v++
			}
		}
		found := false
		for _, x := range p {
			if x == v {
				found = true
			}
		}
		if !found {
			if k > 0 {
				return "", fmt.Sprintf("symbol %d", k)
			}
			return "", "start"
		}
		got = append(got, v)
	}
	if got[0] != start {
		return "", "start"
	}
	if got[len(got)-1] != stop {
		return "", "stop"
	}
	var vals []int
	for k := 1; k < len(got)-1; k++ {
		ix := -1
		for i, x := range p {
			if x == got[k] {
				ix = i
			}
		}
		if ix >= 16 {
			return "", fmt.Sprintf("symbol %d", k)
		}
		vals = append(vals, ix)
	}
	chk := vals[len(vals)-1]
	vals = vals[:len(vals)-1]
	sum := 0
	for i, v := range vals {
		sum += weight(i) * v
	}
	if sum%16 != chk {
		return "", "check"
	}
	var sb strings.Builder
	for _, v := range vals {
		sb.WriteByte(alpha[v])
	}
	return sb.String(), ""
}

func reverse(s string) string {
	b := []byte(s)
	for i, j := 0, len(b)-1; i < j; i, j = i+1, j-1 {
		b[i], b[j] = b[j], b[i]
	}
	return string(b)
}

func decode(bars string) string {
	if strings.Trim(bars, "#.") != "" {
		return "error: char"
	}
	s := strings.Trim(bars, ".")
	if s == "" {
		return "error: empty"
	}
	runs := runsOf(s)
	for _, r := range runs {
		if r != 1 && r != w {
			return "error: width"
		}
	}
	if len(runs)%6 != 1 || len(runs) < 25 {
		return "error: structure"
	}
	text, code := attempt(s)
	if both && code != "" && (code == "terminator" || code == "start") {
		t2, c2 := attempt(reverse(s))
		if c2 == "" || (c2 != "terminator" && c2 != "start") {
			text, code = t2, c2
		}
	}
	if code != "" {
		return "error: " + code
	}
	return text
}

// Barcode encodes or decodes a barcode.
func Barcode(op, text string) string {
	if op == "encode" {
		return encode(text)
	}
	if hasDecode && op == "decode" {
		return decode(text)
	}
	return "error: op"
}

