#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "barcode.h"

#define ALPHA "NMHCO6X8/JE$-ZKL"
#define W 2
#define WEIGHT_KIND 1
#define SWAP 0
#define HAS_DECODE 1
#define BOTH 1

static int PATS[20];

static void init_pats(void) {
    int n = 0;
    for (int p = 0; p < 64; p++) {
