	hasDecode = true
	both      = true
)

func pats() []int {
	var p []int
	for i := 0; i < 64; i++ {
		if bits.OnesCount(uint(i)) == 3 {
			p = append(p, i)
		}
	}
	return p
}

func weight(i int) int {
	switch weightK {
	case "inc":
		return i + 1
	case "odd":
		return 2*i + 1
	}
	if i%2 == 0 {
		return 1
	}
	return 3
}

func startStop() (int, int) {
	p := pats()
	if swap {
		return p[17], p[16]
	}
	return p[16], p[17]
}

func symBars(p int) string {
	var sb strings.Builder
	for j := 0; j < 6; j++ {
		bit := (p >> (5 - j)) & 1
		ch := "#"
		if j%2 == 1 {
			ch = "."
		}
		n := 1
		if bit == 1 {
